def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count numbers in [low, high] divisible by k with equal even/odd digits."""
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(int(ch) for ch in str(bound))

        @lru_cache(maxsize=None)
        def dp(pos: int, remainder: int, balance: int,
               started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and remainder == 0 and balance == 0)
            upper = digits[pos] if tight else 9
            total = 0
            for digit in range(upper + 1):
                next_tight = tight and digit == upper
                if not started and digit == 0:
                    total += dp(pos + 1, remainder, balance, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(pos + 1, next_remainder, next_balance,
                                True, next_tight)
            return total

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)
